import numpy as np


class BisectionBalancedMixedES:
    """
    Steady-state (mu + 1) mixed-integer ES with:
    - Deb's feasibility rules with a balanced, frequency-weighted violation measure,
      so the hardest constraints drive selection.
    - Boundary bisection chains between the most-nearly-feasible infeasible
      individual and the best feasible point (locates the feasibility boundary
      precisely and injects feasible points near good solutions).
    - Differential-style moves on continuous genes, self-adaptive step sizes for
      continuous genes, ordinal/random-reset moves for discrete genes.
    - Single-gene exploitation around the best feasible point.
    - Partial restarts on stagnation that keep the elite.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        d = self.dim
        lb = np.asarray(func.bounds.lb, dtype=float)
        ub = np.asarray(func.bounds.ub, dtype=float)
        vt = list(func.variable_types)

        cont = np.array([i for i in range(d) if vt[i] == "continuous"], dtype=int)
        disc = np.array([i for i in range(d) if vt[i] != "continuous"], dtype=int)
        ordinal_mask = np.array([vt[i] == "ordinal" for i in disc], dtype=bool)

        nv = np.ones(d, dtype=int)
        for i in disc:
            nv[i] = int(func.n_values[i])

        ncon = int(func.n_constraints)
        rs = np.random

        cnt_eval = 0
        cnt_viol = np.zeros(ncon)
        sum_viol = np.zeros(ncon)
        scale = np.ones(ncon)
        wfreq = np.ones(ncon)

        best = {"f": np.inf, "x": None}
        used = 0

        def repair(x):
            x = np.asarray(x, dtype=float).copy()
            if len(cont):
                x[cont] = np.clip(x[cont], -1.0, 1.0)
            if len(disc):
                x[disc] = np.clip(np.rint(x[disc]), 0, nv[disc] - 1)
            return x

        def update_scales():
            mean_pos = sum_viol / np.maximum(cnt_viol, 1.0)
            scale[:] = np.where(cnt_viol > 0, np.maximum(mean_pos, 1e-8), 1.0)
            if cnt_eval > 0:
                wfreq[:] = 1.0 + cnt_viol / cnt_eval

        def evaluate(x, sigma):
            nonlocal used, cnt_eval
            x = repair(x)
            f, g = func(x)
            used += 1
            f = float(f)
            g = np.nan_to_num(np.asarray(g, dtype=float).ravel(),
                              nan=1.0, posinf=1e6, neginf=0.0)
            g = np.maximum(g, 0.0)
            if g.size != ncon:
                g = np.resize(g, ncon)
            if not np.isfinite(f):
                f = np.inf

            cnt_eval += 1
            mask = g > 0
            cnt_viol[:] += mask
            sum_viol[:] += g * mask
            update_scales()

            feas = (not np.any(mask)) and np.isfinite(f)
            if feas and f < best["f"]:
                best["f"] = f
                best["x"] = x.copy()
            return {"x": x, "f": f, "g": g, "feas": feas, "s": sigma}

        def viol_of(ind):
            return float(np.sum(wfreq * ind["g"] / scale))

        def key(ind):
            if ind["feas"]:
                return (0, ind["f"], 0.0)
            v = viol_of(ind)
            if not np.isfinite(ind["f"]):
                v += 1.0
            return (1, 0.0, v)

        def random_point():
            x = np.empty(d, dtype=float)
            if len(cont):
                x[cont] = rs.uniform(-1.0, 1.0, len(cont))
            if len(disc):
                x[disc] = rs.randint(0, nv[disc])
            return x

        def mutate_discrete(x, j):
            idx = disc[j]
            n = nv[idx]
            if n <= 1:
                return
            old = int(x[idx])
            if ordinal_mask[j] and rs.rand() < 0.5:
                step = 1 if rs.rand() < 0.5 else -1
                new = old + step
                if 0 <= new < n:
                    x[idx] = new
                    return
            v = rs.randint(n - 1)
            if v >= old:
                v += 1
            x[idx] = v

        cont_set = set(cont.tolist())

        def mutate_single_gene(x):
            k = rs.randint(d)
            if k in cont_set:
                x[k] = x[k] + 0.05 * rs.randn()
            else:
                j = int(np.where(disc == k)[0][0])
                mutate_discrete(x, j)
            return x

        mu = max(6, min(30, 2 * d))
        n_init = min(self.budget, 4 * mu)
        sigma0 = 0.2
        tau = 1.0 / np.sqrt(max(1, len(cont)))
        pm_disc = 1.0 / max(1, len(disc))
        stag_limit = max(30 * mu, 20 * d)

        pop = []

        def insert(child):
            # (mu+1) replacement by Deb's rules
            if len(pop) < mu:
                pop.append(child)
                return
            worst_idx = max(range(len(pop)), key=lambda k: key(pop[k]))
            if key(child) < key(pop[worst_idx]):
                pop[worst_idx] = child

        for _ in range(n_init):
            if used >= self.budget:
                break
            pop.append(evaluate(random_point(), sigma0))
        pop = sorted(pop, key=key)[:mu]

        def tournament():
            i, j = rs.randint(len(pop)), rs.randint(len(pop))
            return pop[i] if key(pop[i]) <= key(pop[j]) else pop[j]

        def bisect_chain(a_x, b_x, steps=3):
            # a_x infeasible, b_x feasible; bisect to locate the boundary
            for _ in range(steps):
                if used >= self.budget or b_x is None:
                    break
                m = 0.5 * (a_x + b_x)
                c = evaluate(m, sigma0 * 0.3)
                insert(c)
                if c["feas"]:
                    b_x = c["x"]
                else:
                    a_x = c["x"]

        ref_key = min(key(p) for p in pop) if pop else None
        last_improve = used

        while used < self.budget and pop:
            r = rs.rand()
            if r < 0.05:
                child = evaluate(random_point(), sigma0)
                insert(child)

            elif r < 0.12 and best["x"] is not None:
                x = best["x"].copy()
                x = mutate_single_gene(x)
                child = evaluate(x, sigma0 * 0.5)
                insert(child)

            elif r < 0.20 and best["x"] is not None:
                # bisection chain: most nearly feasible infeasible parent vs best feasible
                infeas = [p for p in pop if not p["feas"]]
                if infeas:
                    a = min(infeas, key=viol_of)
                    bisect_chain(a["x"], best["x"].copy(), steps=3)
                else:
                    child = evaluate(random_point(), sigma0)
                    insert(child)

            else:
                p1 = tournament()
                if rs.rand() < 0.5:
                    p2 = tournament()
                    mask = rs.rand(d) < 0.5
                    x = np.where(mask, p1["x"], p2["x"]).astype(float)
                    sigma = np.sqrt(p1["s"] * p2["s"])
                else:
                    x = p1["x"].copy()
                    sigma = p1["s"]

                sigma = float(np.clip(sigma * np.exp(tau * rs.randn()), 1e-3, 0.5))

                if len(cont):
                    if len(pop) >= 3 and rs.rand() < 0.25:
                        # differential move on continuous genes
                        p2 = tournament()
                        p3 = tournament()
                        F = 0.5 + 0.3 * rs.rand()
                        diff = F * (p2["x"][cont] - p3["x"][cont])
                        x[cont] = x[cont] + diff + 0.01 * rs.randn(len(cont))
                    else:
                        x[cont] = x[cont] + sigma * rs.randn(len(cont))

                if len(disc):
                    for j in range(len(disc)):
                        if rs.rand() < pm_disc:
                            mutate_discrete(x, j)

                child = evaluate(x, sigma)
                insert(child)

            if pop:
                cur_best_key = min(key(p) for p in pop)
                if ref_key is None or cur_best_key < ref_key:
                    ref_key = cur_best_key
                    last_improve = used

            # partial restart on stagnation, keep the elite
            if pop and used - last_improve > stag_limit and used < self.budget:
                elite = min(pop, key=key)
                pop = [elite]
                n_new = min(mu - 1, self.budget - used)
                for _ in range(n_new):
                    if used >= self.budget:
                        break
                    pop.append(evaluate(random_point(), sigma0))
                ref_key = min(key(p) for p in pop)
                last_improve = used

        return best["f"], best["x"]
